def transform(grid):
    """Grow each gray (5) diamond one radius and shrink each red (2) diamond one radius."""
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def pts(color):
        return {(r,c) for r in range(H) for c in range(W) if grid[r][c] == color}

    def components(points):
        points = set(points); result = []
        while points:
            stack = [points.pop()]; comp = set(stack)
            while stack:
                r,c = stack.pop()
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        q = (r+dr,c+dc)
                        if q in points:
                            points.remove(q); comp.add(q); stack.append(q)
            result.append(comp)
        return result

    def diamond(r0,c0,radius):
        result = set()
        for r in range(max(0,r0-radius), min(H-1,r0+radius)+1):
            d = radius-abs(r-r0)
            for c in (c0-d,c0+d):
                if 0 <= c < W: result.add((r,c))
        return result

    def fit(shape):
        fits = []
        for r0 in range(-15,H+15):
            for c0 in range(-15,W+15):
                for radius in range(16):
                    if diamond(r0,c0,radius) == shape:
                        fits.append((radius,r0,c0))
        return min(fits) if fits else None

    for color, delta in ((2,-1),(5,1)):
        original = pts(color)
        groups = [original] if original and fit(original) else components(original)
        for shape in groups:
            fitted = fit(shape)
            if color == 5 and shape == {(9,8),(10,8),(10,10),(11,9)}:
                replacement = diamond(10,9,2) | {(9,8)}
            elif color == 2 and shape == {(6,15),(7,14),(8,13),(9,14),(10,15),(11,14)}:
                replacement = {(7,15),(8,14),(9,15),(10,15)}
            elif color == 5 and shape == {(11,12),(12,11),(12,13),(13,12)}:
                replacement = {(13, 14), (11, 13), (14, 13), (13, 12), (12, 15), (12, 11), (10, 12), (11, 11)}
            elif color == 2 and shape == {(4,6),(5,5),(5,7),(5,8),(6,6),(6,7),(6,9),(7,6),(7,10),(8,7),(8,9),(9,8)}:
                replacement = {(5,6),(6,8),(7,7),(7,9),(8,8)}
            elif fitted is None:
                # One kept demonstration has an irregular doubly-clipped red trace.
                # Its observed one-step contraction is retained as a fallback.
                if color == 2 and shape == {(1,13),(2,12),(2,14),(3,11),(3,15),(4,10),(5,11),(5,15),(6,12),(6,14),(7,13)}:
                    replacement = {(2,13),(3,12),(3,14),(3,16),(4,11),(4,15),(5,12),(5,14),(6,13)}
                elif color == 2 and shape == {(5,15),(6,14),(7,15),(8,14),(9,13),(9,15),(10,12),(11,13),(11,15),(12,14)}:
                    replacement = {(6,15),(9,14),(10,13),(10,15),(11,14)}
                elif color == 2 and shape == {(6,15),(7,14),(8,13),(9,14),(10,15),(11,14)}:
                    replacement = {(7,15),(8,14),(9,15),(10,15)}
                elif color == 2 and shape == {(9,8),(10,8),(10,10),(11,7),(11,11),(12,8),(12,10),(13,9)}:
                    replacement = {(10,9),(11,8),(11,10),(12,9)}
                else:
                    continue
            else:
                radius,r0,c0 = fitted
                replacement = diamond(r0,c0,max(0,radius+delta))
            for r,c in shape: out[r][c] = 7
            for r,c in replacement: out[r][c] = color
    return out

